do $$ begin create type purchase_order_status as enum ('draft','approved','sent','partially_received','received','cancelled'); exception when duplicate_object then null; end $$; do $$ begin create type receipt_status as enum ('posted','voided'); exception when duplicate_object then null; end $$; create table if not exists purchase_orders (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,supplier_id uuid not null references suppliers(id),purchase_plan_id uuid references purchase_plans(id),status purchase_order_status not null default 'draft',order_number text not null,ordered_at timestamptz,approved_at timestamptz,expected_at timestamptz,sent_at timestamptz,received_at timestamptz,cancelled_at timestamptz,created_by uuid references auth.users(id),approved_by uuid references auth.users(id),notes text,created_at timestamptz not null default now(),unique(business_id,order_number)); create table if not exists purchase_order_lines (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,purchase_order_id uuid not null references purchase_orders(id) on delete cascade,ingredient_id uuid not null references ingredients(id),unit text not null,ordered_quantity numeric(24,8) not null check(ordered_quantity>0),received_quantity numeric(24,8) not null default 0 check(received_quantity>=0 and received_quantity<=ordered_quantity),unit_price numeric(24,8) not null check(unit_price>=0),expected_unit_cost numeric(24,8),created_at timestamptz not null default now(),unique(purchase_order_id,ingredient_id)); create table if not exists goods_receipts (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,purchase_order_id uuid not null references purchase_orders(id),receipt_number text not null,status receipt_status not null default 'posted',received_at timestamptz not null default now(),received_by uuid references auth.users(id),notes text,created_at timestamptz not null default now(),unique(business_id,receipt_number)); create table if not exists goods_receipt_lines (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,goods_receipt_id uuid not null references goods_receipts(id) on delete cascade,purchase_order_line_id uuid not null references purchase_order_lines(id),ingredient_id uuid not null references ingredients(id),unit text not null,received_quantity numeric(24,8) not null check(received_quantity>0),unit_price numeric(24,8) not null check(unit_price>=0),inventory_movement_id uuid references inventory_movements(id),ingredient_price_id uuid references ingredient_prices(id),created_at timestamptz not null default now(),unique(goods_receipt_id,purchase_order_line_id)); create table if not exists supplier_execution_metrics (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,supplier_id uuid not null references suppliers(id) on delete cascade,window_orders integer not null default 0,completed_orders integer not null default 0,on_time_orders integer not null default 0,lines_ordered numeric(24,8) not null default 0,lines_fully_received numeric(24,8) not null default 0,avg_lead_time_days numeric(24,8) not null default 0,lead_time_reliability_score numeric(8,4) not null default 0,delivery_completion_score numeric(8,4) not null default 0,calculated_at timestamptz not null default now(),unique(business_id,supplier_id)); alter table purchase_orders enable row level security; alter table purchase_order_lines enable row level security; alter table goods_receipts enable row level security; alter table goods_receipt_lines enable row level security; alter table supplier_execution_metrics enable row level security; create policy v18_po_select on purchase_orders for select using(is_member(business_id)); create policy v18_pol_select on purchase_order_lines for select using(is_member(business_id)); create policy v18_gr_select on goods_receipts for select using(is_member(business_id)); create policy v18_grl_select on goods_receipt_lines for select using(is_member(business_id)); create policy v18_metrics_select on supplier_execution_metrics for select using(is_member(business_id));